'use strict';
const routes={workspace:'Workspace',tools:'Capabilities',objects:'Objects',changes:'Changes',validation:'Validation',communication:'Communication',agent:'Agent access',settings:'Settings'};
const initial=document.body.dataset.entry||'tools';
const basePath='/ActiveEcuC/Can/CanConfigSet/CanController_0/CanControllerBaudrateConfig_0';
const objectSeed=[{id:'baud',name:'CanControllerBaudrateConfig_0',kind:'ecuc-container',path:basePath,file:'Config/Can.arxml',refs:[]},{id:'signal',name:'VehicleSpeed',kind:'signal',path:'/Vehicle/Signals/VehicleSpeed',file:'communication.arxml',refs:[]},{id:'pdu',name:'Pdu_VehicleSpeed',kind:'pdu',path:'/Vehicle/Pdus/Pdu_VehicleSpeed',file:'communication.arxml',refs:['signal']},{id:'frame',name:'Frame_VehicleSpeed',kind:'frame',path:'/Vehicle/Frames/Frame_VehicleSpeed',file:'communication.arxml',refs:['pdu']},{id:'interface',name:'IF_VehicleSpeed',kind:'port-interface',path:'/Vehicle/Interfaces/IF_VehicleSpeed',file:'software.arxml',refs:[]},{id:'swc',name:'SpeedSensor',kind:'software-component',path:'/Vehicle/SwCs/SpeedSensor',file:'software.arxml',refs:['interface'],unresolved:'/Vehicle/Interfaces/IF_Calibration'},{id:'map',name:'Map_VehicleSpeed',kind:'unknown',path:'/Vehicle/FrameMappings/Map_VehicleSpeed',file:'communication.arxml',refs:['frame']},{id:'ecu',name:'Gateway',kind:'ecu',path:'/Vehicle/Ecus/Gateway',file:'communication.arxml',refs:['frame']}];
const defaults={view:routes[initial]?initial:'tools',tab:document.body.dataset.tab||'vendor',vendor:'vector',revision:12,value:500,pending:null,undo:null,history:[],runs:[],structural:null,selectedObject:'baud',query:'',kind:'all',catalogRegion:'all',catalogQuery:'',contractQuery:'',contractType:'all',binding:{vendor:'vector',project:'Gateway',toolVersion:'6.4',package:'MICROSAR example package',location:'C:/Examples/Gateway/Gateway.dvjson'},bindingVersion:1,theme:'light'};
let restored=null;try{restored=JSON.parse(sessionStorage.getItem('autarx-workbench-v3'))}catch{}
const state={...defaults,...(restored?.schema===3?restored.data:{}),view:defaults.view,tab:defaults.tab,busy:false};
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Display only: break opportunities after path separators, so a wrapped AUTOSAR path breaks at a segment boundary instead of inside a name.
const pathMarkup=s=>String(s).replace(/\//g,'/<wbr>');
function save(){try{const {busy,...data}=state;sessionStorage.setItem('autarx-workbench-v3',JSON.stringify({schema:3,data}));return true}catch{return false}}
function notify(s){$('#feedback').textContent=s}
const chip=(label,tone='')=>`<span class="badge ${tone}">${esc(label)}</span>`;
const button=(label,action,primary=false,disabled=false)=>`<button type="button" data-action="${action}" class="${primary?'primary':''}" ${disabled?'disabled':''}>${label}</button>`;
const go=(view,label)=>`<button type="button" data-go="${view}">${label}</button>`;
const panel=(title,body,meta='')=>`<section class="panel"><div class="panelhead"><h2>${title}</h2>${meta}</div><div class="pad">${body}</div></section>`;
const kv=(label,value)=>`<div class="kv"><dt>${label}</dt><dd>${value}</dd></div>`;
const field=(label,id,value,type='text',help='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${help?`aria-describedby="${id}-help"`:''}>${help?`<p class="note" id="${id}-help">${help}</p>`:''}</div>`;
const select=(label,id,options,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
const head=(title,description,action='')=>`<div class="pagehead"><div><div class="eyebrow">AUTARX / ENGINEERING TOOL LAYER</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const currentEvidence=r=>r&&r.revision===state.revision&&r.bindingVersion===state.bindingVersion;
const latest=()=>state.runs[0];
const bound=()=>state.binding;
const readiness=()=>bound().vendor!=='vector'?'Adapter not integrated':!bound().package.trim()?'Configuration package missing':!bound().location.trim()?'Project location missing':!bound().toolVersion.trim()?'Tool version missing':'Ready for example execution';
const ready=()=>readiness()==='Ready for example execution';
const resultNames={pass:'Passed',fail:'Failed',partial:'Partial',error:'Execution failed'};
const tones={pass:'ok',fail:'bad',partial:'warn',error:'bad'};
function evidenceSummary(){const r=latest();return !r?'Not run':!currentEvidence(r)?'Stale evidence':resultNames[r.outcome]}
function workspacePage(){return head('Engineering context, connected.','One workspace for configuration operations, supplier capabilities and evidence. The external agent controls the workflow.',chip('Example workspace'))+`<div class="metrics"><div class="metric od-stat"><strong>${String(state.revision).padStart(2,'0')}</strong><span>Configuration revision</span></div><div class="metric od-stat"><strong>${objectSeed.length}</strong><span>Indexed example objects</span></div><div class="metric od-stat"><strong>${state.runs.length}</strong><span>Explicit vendor invocations</span></div></div><div class="split">${panel('Gateway / ECU_01',`<dl>${kv('Project',esc(bound().project))}${kv('Target tool',esc(vendors[bound().vendor].name))}${kv('Version',esc(bound().toolVersion)||'Unspecified')}${kv('Package',esc(bound().package)||'Missing')}${kv('Binding',`Environment ${state.bindingVersion} · ${readiness()}`)}</dl><div class="actions sectiongap">${go('settings','Edit engineering binding')}${go('tools','Inspect capabilities')}</div>`)}${panel('Evidence at a glance',`<div class="od-cluster">${chip(evidenceSummary(),latest()&&!currentEvidence(latest())?'warn':latest()?tones[latest().outcome]:'')}${chip('Simulated')}</div><p class="note sectiongap">${latest()?`Recorded against revision ${latest().revision}, environment ${latest().bindingVersion}.`:'No supplier validation has executed in this example workspace.'}</p><div class="actions sectiongap">${go('validation','Open validation')}${go('changes','Review changes')}</div>`)}</div><div class="toolgrid sectiongap">${panel('Structural inspection',`<p>References and object identity</p><p class="note sectiongap">${state.structural?`Last example inspection: revision ${state.structural.revision}.`:'No structural inspection recorded.'} Structural checks do not establish supplier acceptance.</p><div class="actions sectiongap">${go('objects','Browse objects')}<button data-go="validation" data-tab="structural">Inspect references</button></div>`)}${panel('Agent interface',`<p>Discover → query → change → validate</p><p class="note sectiongap">Autarx exposes bounded tools and traceable results. It does not plan tasks or retry on behalf of an agent.</p><div class="actions sectiongap">${go('agent','View tool contracts')}</div>`)}</div>`}
function toolsPage(){const all=Object.entries(vendors);const shown=all.filter(([id,v])=>(state.catalogRegion==='all'||(state.catalogRegion==='cn')===(v.region==='Mainland China'))&&(v.name+' '+v.label).toLowerCase().includes(state.catalogQuery.toLowerCase()));const v=vendors[state.vendor];return head('Discover callable capabilities.','Product coverage, adapter readiness and engineering prerequisites are separate facts.')+`<div class="metrics"><div class="metric od-stat"><strong>${all.length}</strong><span>Catalog targets</span></div><div class="metric od-stat"><strong>${all.filter(([,v])=>v.region==='Mainland China').length}</strong><span>Mainland China targets</span></div><div class="metric od-stat"><strong>0</strong><span>Live integrations in prototype</span></div></div><div class="split"><section class="panel"><div class="panelhead"><h2>Vendor coverage</h2>${button('Refresh example','scan')}</div><div class="pad toolbar">${field('Search vendors','catalogQuery',state.catalogQuery,'search')}${select('Coverage','catalogRegion',[['all','All targets'],['cn','Mainland China'],['global','International']],state.catalogRegion)}</div>${shown.map(([id,t])=>`<button type="button" class="tool ${id===state.vendor?'selected':''}" data-vendor="${id}" aria-pressed="${id===state.vendor}"><span class="toolmark">${t.mark}</span><span class="tooltext"><strong>${esc(t.name)}</strong><small>${esc(t.label)} · ${esc(t.region||'International')}</small><small>${esc(t.version)}</small></span><span class="toolstatus">${chip(id==='vector'?'Example ready':id==='eb'?'Example blocked':'Planned',id==='vector'?'ok':id==='eb'?'warn':'')}</span></button>`).join('')||'<div class="pad">No matching vendors. Clear the search or change coverage.</div>'}<div class="pad note">Catalog coverage is not exhaustive. Planned entries expose no executable operations.</div></section>${panel(esc(v.label),`<p class="note">${esc(v.detail)}</p><dl class="sectiongap">${kv('Installation',state.vendor==='vector'?'Example installation only':state.vendor==='eb'?'Example installation · unverified':'Not configured')}${kv('Bound project',bound().vendor===state.vendor?esc(bound().project):'Not bound to this vendor')}${kv('Environment',bound().vendor===state.vendor?readiness():'Select this target in Settings')}</dl>${v.caps.map(c=>`<div class="cap"><strong>${esc(c[0])}</strong>${chip(c[1],v.tone)}<p>${esc(c[2])}</p></div>`).join('')}${v.source?`<details><summary>Product evidence</summary><p class="note sectiongap">Product documentation does not by itself prove a callable integration.</p><a href="${esc(v.source)}" target="_blank" rel="noopener noreferrer">Official product / ecosystem reference</a></details>`:''}<div class="actions sectiongap">${go('settings','Configure binding')}${go('agent','View contracts')}</div>`)}</div>`}
function objectsPage(){const list=objectSeed.filter(o=>(state.kind==='all'||o.kind===state.kind)&&(o.name+' '+o.path+' '+o.kind).toLowerCase().includes(state.query.toLowerCase()));const o=objectSeed.find(x=>x.id===state.selectedObject)||objectSeed[0];const incoming=objectSeed.filter(x=>x.refs.includes(o.id));return head('Objects with their context.','Inspect identities, references and definition-addressed values before preparing a change.',chip('Revision '+state.revision))+`<div class="toolbar">${field('Find an object','objectQuery',state.query,'search')}${select('Semantic kind','kind',[['all','All kinds'],...Array.from(new Set(objectSeed.map(o=>o.kind))).map(k=>[k,k])],state.kind)}</div><div class="split"><section class="panel"><div class="panelhead"><h2>Configuration objects</h2><span class="small muted">${list.length} of ${objectSeed.length}</span></div>${list.map(x=>`<button class="tool ${o.id===x.id?'selected':''}" data-object="${x.id}" aria-pressed="${o.id===x.id}"><span class="tooltext"><strong>${x.name}</strong><small class="mono">${pathMarkup(x.path)}</small></span><span class="toolstatus">${chip(x.kind)}${x.unresolved?chip('Unresolved','bad'):''}</span></button>`).join('')||'<div class="pad">No objects match. Clear the search or choose another kind.</div>'}</section>${panel(esc(o.name),`<p class="mono">${pathMarkup(o.path)}</p><dl class="sectiongap">${kv('Kind',chip(o.kind))}${kv('Source',`<code>${o.file}</code>`)}${o.id==='baud'?kv('Parameter','<code>CanControllerBaudRate</code>')+kv('Value',`${state.value} kbit/s`):''}</dl><h3 class="sectiongap">Incoming references · ${incoming.length}</h3>${incoming.map(x=>`<button class="refbutton" data-object="${x.id}"><span>${x.name}</span><span class="mono">${pathMarkup(x.path)}</span></button>`).join('')||'<p class="note">No incoming references in this example.</p>'}<h3 class="sectiongap">Outgoing references · ${o.refs.length+(o.unresolved?1:0)}</h3>${o.refs.map(id=>{const x=objectSeed.find(y=>y.id===id);return `<button class="refbutton" data-object="${id}"><span>${x.name}</span><span class="mono">${pathMarkup(x.path)}</span></button>`}).join('')}${o.unresolved?`<div class="callout sectiongap">${chip('Unresolved','bad')}<p class="mono sectiongap">${pathMarkup(o.unresolved)}</p><p class="note">Target is absent from the example delivery. No replacement is inferred.</p></div>`:''}${!o.refs.length&&!o.unresolved?'<p class="note">No outgoing references in this example.</p>':''}<div class="actions sectiongap">${button('Copy full path','copyPath')}${o.id==='baud'?go('changes','Prepare parameter change'):''}${o.id==='swc'?'<button data-go="validation" data-tab="structural">Inspect finding</button>':''}</div>`)}</div>`}
function changeDelta(before,after){return `<div class="delta"><div class="od-stat"><span class="small muted">Before</span><strong>${before}</strong><span class="small">kbit/s</span></div><div class="od-stat after"><span class="small">After</span><strong>${after}</strong><span class="small">kbit/s</span></div></div>`}
function changesPage(){const pending=state.pending;const stale=pending&&(pending.revision!==state.revision||pending.bindingVersion!==state.bindingVersion);return head('Review exactly what will change.','Every write is bound to the configuration and environment you reviewed. Supplier validation remains a separate operation.',chip('Revision '+state.revision))+`<div class="split">${panel('Prepare a change',`<p class="mono">${pathMarkup(basePath)}</p><dl class="sectiongap">${kv('Definition','<code>CanControllerBaudRate</code>')}${kv('Current',`${state.value} kbit/s`)}</dl>${field('New baud rate · kbit/s','baud',state.draft??250,'number','Example input constraint: integer 1–1000. This does not establish hardware suitability.')}<p id="changeError" class="error" hidden></p><div class="actions">${button('Prepare preview','prepare',true,state.busy)}</div>`)}${panel('Semantic diff',pending?`${chip(stale?'Preview stale':'Ready to review',stale?'warn':'')}<p class="note sectiongap">One parameter · Config/Can.arxml · based on revision ${pending.revision}, environment ${pending.bindingVersion}</p>${changeDelta(pending.before,pending.after)}<p class="note">No containers, references or modules are removed. The example snapshot remains available for one-step Undo.</p><div class="actions sectiongap">${button('Apply reviewed change','confirm',true,!!stale||state.busy)}${button('Discard preview','discard',false,state.busy)}</div>${stale?'<p class="error sectiongap">Prepare a new preview against the current context.</p>':''}`:'<div class="callout"><strong>No pending change</strong><p class="note">Enter a value and prepare a diff. Nothing is written during preparation.</p></div>')}</div><div class="split sectiongap">${panel('Applied changes',state.history.length?state.history.map(h=>`<div class="record"><div class="od-cluster">${chip(h.kind==='undo'?'Restored':'Applied')}${chip('Revision '+h.revision)}</div><p class="mono">CanControllerBaudRate: ${h.before} → ${h.after} kbit/s</p><p class="note">${h.kind==='undo'?'Undo creates a new revision.':'Previous evidence remains bound to its original context.'}</p></div>`).join(''):'<p class="note">No changes applied in this example workspace.</p>')}${panel('Configuration & evidence',`<dl>${kv('Current revision',state.revision)}${kv('Current value',`${state.value} kbit/s`)}${kv('Vendor evidence',evidenceSummary())}</dl><div class="actions sectiongap">${button('Undo last change','undo',false,!state.undo||state.busy)}${go('validation','Open validation')}</div>`)}</div>`}
function recordMarkup(r){if(!r)return '<div class="callout"><strong>No vendor evidence yet.</strong><p class="note">Run an explicit check against the bound environment. No real process is invoked in this prototype.</p></div>';return `<div class="od-cluster">${chip(resultNames[r.outcome],tones[r.outcome])}${chip(currentEvidence(r)?'Current':'Stale',currentEvidence(r)?'':'warn')}${chip('Simulated')}</div><h3 class="sectiongap">${({pass:'Requested example checks completed.',fail:'Configuration was rejected.',partial:'Requested coverage is incomplete.',error:'No valid check result was produced.'})[r.outcome]}</h3><dl>${kv('Evidence',`<code>${r.id}</code>`)}${kv('Tool',esc(r.tool)+' · '+esc(r.version))}${kv('Package',esc(r.package))}${kv('Context',`Revision ${r.revision} · environment ${r.bindingVersion}`)}${kv('Scope',r.scope==='all'?'All project modules':'Can module only')}${kv('Threshold','Error · warnings retained')}</dl>${r.outcome==='fail'?`<div class="finding"><strong>Illustrative timing diagnostic</strong><p class="note">Controller timing requires review for the requested baud rate. This is an example, not an actual supplier rule.</p><code>${pathMarkup(basePath)}</code><div class="actions">${button('Locate configuration','locateBaud')}${go('changes','Review change')}</div></div>`:r.outcome==='partial'?'<p class="note sectiongap">An external step did not complete. Completed checks cannot establish full requested coverage.</p>':r.outcome==='error'?'<p class="note sectiongap">Example license checkout failed. No checks ran; configuration validity is unknown.</p>':'<p class="note sectiongap">Passing this scope does not prove system requirements or checks outside this invocation.</p>'}${!currentEvidence(r)?'<p class="error sectiongap">Configuration or environment changed after this run. Evidence is stale.</p>':''}<details><summary>Original output · simulated</summary><pre>${esc(r.raw)}</pre></details><div class="actions sectiongap">${button('Export evidence JSON','exportEvidence')}</div>`}
function structuralPage(){const r=state.structural;return `<div class="split">${panel('Autarx structural inspection',`<p class="note">Checks example object identity and reference resolution only. It does not replace vendor validation.</p><div class="actions sectiongap">${button(state.busy?'Inspecting…':'Run example inspection','inspect',true,state.busy)}</div>${r?`<div class="od-cluster sectiongap">${chip('1 unresolved','bad')}${chip(r.revision===state.revision?'Current':'Stale',r.revision===state.revision?'':'warn')}</div><p class="note sectiongap">${objectSeed.length} objects · 0 duplicate paths · revision ${r.revision}</p>`:'<div class="callout sectiongap">No structural inspection recorded.</div>'}`)}${panel('Structural findings',r?`<div class="finding"><strong>Unresolved required interface</strong><p class="mono">${pathMarkup('/Vehicle/SwCs/SpeedSensor/CalibrationIn')}</p><p class="note">REQUIRED-INTERFACE-TREF points to:</p><code>${pathMarkup('/Vehicle/Interfaces/IF_Calibration')}</code><p class="note">The target is absent. Import its owning delivery or review the intended reference; no replacement is inferred.</p>${button('Locate source object','locateSwc')}</div>`:'<p class="note">Run inspection to list findings. Empty history does not mean that the configuration passes.</p>')}</div>`}
function validationPage(){const tabs=`<div class="tabs" role="group" aria-label="Validation source"><button data-tab="vendor" aria-pressed="${state.tab!=='structural'}">Supplier validation</button><button data-tab="structural" aria-pressed="${state.tab==='structural'}">Structural inspection</button></div>`;if(state.tab==='structural')return head('Checks with explicit authority.','Structural inspection and supplier validation keep separate results and claims.')+tabs+structuralPage();const r=state.runs.find(x=>x.id===state.recordId)||latest();return head('Validation with evidence.','Bind the supplier, version, package, check scope and configuration revision to each result.')+tabs+`<div class="split">${panel('Bound execution environment',`<dl>${kv('Project',esc(bound().project))}${kv('Tool',esc(vendors[bound().vendor].name))}${kv('Version',esc(bound().toolVersion)||'Missing')}${kv('Package',esc(bound().package)||'Missing')}</dl><p class="${ready()?'note':'error'}">${readiness()}</p><div class="actions sectiongap">${go('settings','Edit binding')}</div><div class="sectiongap">${select('Requested scope','scope',[['all','All project modules'],['can','Can module only']],state.scope||'all')}</div><details><summary>Illustrative response fixture</summary><p class="note sectiongap">Choose an example to inspect result semantics. This does not change a supplier rule.</p>${select('Example response','outcome',[['fail','Configuration rejected'],['pass','Selected checks pass'],['partial','Partial completion'],['error','Execution failure']],state.outcome||'fail')}</details><div class="actions sectiongap">${button(state.busy?'Running example…':'Run example validation','run',true,!ready()||state.busy)}</div>${state.busy?'<div class="progress" role="progressbar" aria-label="Example check running"><div></div></div>':''}<p class="note sectiongap">One explicit invocation. No automatic repair or retry.</p>`)}${panel('Execution evidence',recordMarkup(r))}</div><section class="panel sectiongap"><div class="panelhead"><h2>Run history</h2><span class="small muted">${state.runs.length} records</span></div>${state.runs.map(x=>`<button class="tool" data-record="${x.id}"><span class="tooltext"><strong>${x.id}</strong><small>Revision ${x.revision} · environment ${x.bindingVersion} · ${x.scope==='all'?'All modules':'Can only'}</small></span><span class="toolstatus">${chip(resultNames[x.outcome],tones[x.outcome])}${!currentEvidence(x)?chip('Stale','warn'):''}</span></button>`).join('')||'<div class="pad note">No invocations recorded.</div>'}</section>`}
function communicationPage(){return head('Follow the communication chain.','A focused view of the example signal, PDU, frame and owning ECU. Model relationships do not imply bus timing validity.')+panel('VehicleSpeed · dependency path',`<div class="chain">${['signal','pdu','frame','ecu'].map((id,i)=>{const o=objectSeed.find(x=>x.id===id);return `<button data-object="${id}" class="chainitem"><span class="small muted">0${i+1} / ${o.kind}</span><strong>${o.name}</strong><span class="mono">${pathMarkup(o.path)}</span><span class="small">Inspect object →</span></button>`}).join('')}</div><div class="callout sectiongap">All links are seeded example relationships. Bus timing, routing and supplier-specific checks require a bound tool invocation.</div><div class="actions sectiongap">${go('validation','Open supplier validation')}${go('objects','Browse all objects')}</div>`)}
const contractList=[['capabilities.list','Read','Discover supported operations and version-specific prerequisites.'],['configuration.query','Read','Resolve an object or definition-addressed parameter.'],['configuration.change','Write','Prepare/apply a reviewed change with expected configuration and environment versions.'],['vendor.validate','Execute','Invoke the bound supplier and preserve the original diagnostic evidence.'],['vendor.generate','Execute','Request supplier code generation where supported; distinct from validation.']];
function requestFor(name){const context={project:bound().project,expected_revision:state.revision,expected_environment:state.bindingVersion};return name==='capabilities.list'?{project:bound().project}:name==='configuration.query'?{...context,path:basePath}:name==='configuration.change'?{...context,operation:'set-value',path:basePath,definition:'CanControllerBaudRate',value:state.pending?.after??250}:name==='vendor.validate'?{...context,adapter:bound().vendor,scope:state.scope||'all',fail_on:'error'}:{...context,adapter:bound().vendor}}
function responseFor(name){if(name==='capabilities.list')return {simulation:true,live_integrations:0,bound_adapter:bound().vendor,readiness:readiness(),catalog:Object.keys(vendors),callable_example_operations:ready()?['validate']:[]};if(name==='configuration.query')return {simulation:true,revision:state.revision,environment:state.bindingVersion,path:basePath,value:state.value,unit:'kbit/s'};if(name==='configuration.change')return {simulation:true,preview:state.pending,status:state.pending?'prepared':'not_prepared',conflict_policy:'reject stale revision or environment'};if(name==='vendor.validate')return {simulation:true,latest:latest()?{...latest(),stale:!currentEvidence(latest())}:null};return {simulation:true,status:'not_run',reason:'No actual supplier generator is connected'}}
function agentPage(){const list=contractList.filter(c=>(state.contractType==='all'||c[1]===state.contractType)&&(c[0]+' '+c[2]).toLowerCase().includes(state.contractQuery.toLowerCase()));return head('An interface your agent can use.','Discover, inspect, change and validate. Planning and retry decisions remain with the external agent.')+`<div class="callout caption"><strong>Proposed tool contracts</strong><p class="note">No MCP server or agent is connected. Requests and responses below track the current prototype state.</p></div><div class="toolbar">${field('Find an operation','contractQuery',state.contractQuery,'search')}${select('Operation type','contractType',[['all','All types'],['Read','Read'],['Write','Write'],['Execute','Execute']],state.contractType)}</div><div class="toolgrid">${list.map(([name,type,description])=>panel(`<span class="mono">${name}</span>`,`<p class="note caption">${description}</p><h3 class="small caption">Example request</h3><pre class="codebox">${pathMarkup(esc(JSON.stringify(requestFor(name),null,2)))}</pre><details><summary>Current structured response</summary><pre>${esc(JSON.stringify(responseFor(name),null,2))}</pre></details><div class="actions sectiongap"><button data-contract="${name}">Copy request</button>${go(name==='configuration.change'?'changes':name==='configuration.query'?'objects':name==='vendor.validate'?'validation':'tools','Open related view')}</div>`,chip(type))).join('')}</div>${!list.length?'<div class="callout">No matching operations. Clear the search or change the type.</div>':''}<div class="callout sectiongap"><strong>Stable result semantics</strong><p class="note">Passed, Failed, Partial and Execution failed remain distinct. Missing checks never become a pass. Evidence carries its original scope and context; stale evidence remains inspectable.</p></div>`}
function settingsPage(){return head('Bind the engineering environment.','Keep the exact supplier, version and configuration package explicit. Changing the binding invalidates prior evidence.',chip('Environment '+state.bindingVersion))+`<div class="split">${panel('Project binding',`${field('Project name','bindingProject',bound().project)}${select('Target tool','bindingVendor',Object.entries(vendors).map(([id,v])=>[id,v.name]),bound().vendor)}${field('Installed tool version','bindingToolVersion',bound().toolVersion)}${field('BSW / MCAL / module package','bindingPackage',bound().package,'text','A label in this prototype, not a verified package or filesystem path.')} ${field('Project file location','bindingLocation',bound().location,'text','Typed example only. No local file is opened.')}<p class="error" id="bindingError" hidden></p><div class="actions">${button('Save example binding','saveBinding',true,state.busy)}</div>`)}${panel('Readiness & appearance',`<dl>${kv('Current readiness',readiness())}${kv('Real tool processes','Not connected')}${kv('Agent server','Not connected')}${kv('Storage','Browser-session best effort; memory fallback')}</dl><p class="note sectiongap">Only the Vector example supports simulated invocation. Saving a domestic target does not install or implement its adapter.</p><h3 class="sectiongap">Appearance</h3><div class="actions sectiongap">${button(state.theme==='dark'?'Use light appearance':'Use dark appearance','theme')}</div><h3 class="sectiongap">Updates</h3><p class="note">No installed product version or update service is connected. No update availability is asserted.</p><div class="actions sectiongap">${go('tools','Inspect coverage')}${go('agent','View proposed tools')}</div>`)}</div>`}
function render(){document.documentElement.dataset.theme=state.theme;$('#theme').textContent=state.theme==='dark'?'Light appearance':'Dark appearance';$('#crumb').textContent=routes[state.view];$('#projectLabel').textContent=bound().project;$('#contextRevision').textContent=`r${state.revision} · env ${state.bindingVersion}`;$('#workspaceLabel').textContent=bound().project+' / ECU_01';document.querySelectorAll('nav [data-go]').forEach(b=>b.setAttribute('aria-current',b.dataset.go===state.view?'page':'false'));$('#mobileNav').value=state.view;$('#screen').innerHTML=({workspace:workspacePage,tools:toolsPage,objects:objectsPage,changes:changesPage,validation:validationPage,communication:communicationPage,agent:agentPage,settings:settingsPage})[state.view]();save()}
function navigate(view,tab){if(!routes[view])return;state.view=view;if(tab)state.tab=tab;notify('');render();const heading=$('#screen h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})}
function copy(text){navigator.clipboard?.writeText(text).then(()=>notify('Copied.'),()=>fallbackCopy(text))??fallbackCopy(text)}
function fallbackCopy(text){openDialog('Copy content',`<label for="copyText">Clipboard unavailable. Select and copy:</label><textarea id="copyText" readonly>${esc(text)}</textarea>`,'Close',null)}
let dialogAction=null;let dialogTrigger=null;
function openDialog(title,body,label,action){dialogTrigger=document.activeElement;dialogAction=action;$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialogConfirm').textContent=label;$('#dialogCancel').hidden=!action;$('#dialog').showModal();(action?$('#dialogCancel'):$('#dialogConfirm')).focus()}
function prepare(){if(state.busy){notify('Wait until the example inspection or validation completes.');return}const input=$('#baud');if(!input)return;const value=Number(input.value);const error=$('#changeError');if(!input.value||!Number.isInteger(value)||value<1||value>1000||value===state.value){error.hidden=false;error.textContent=value===state.value?'Choose a value different from the current value.':'Enter a whole number from 1 to 1000.';input.setAttribute('aria-invalid','true');input.focus();return}state.draft=value;state.pending={before:state.value,after:value,revision:state.revision,bindingVersion:state.bindingVersion};render();$('#screen [data-action="confirm"]')?.focus({preventScroll:true});notify('Preview prepared. No configuration write or vendor validation has occurred.')}
function exportRecord(){const r=state.runs.find(x=>x.id===state.recordId)||latest();if(!r)return;download('autarx-example-'+r.id+'.json',{...r,stale:!currentEvidence(r)})}
function download(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Example JSON export requested.')}
function execute(){if(state.busy||!ready())return;const invocation={revision:state.revision,bindingVersion:state.bindingVersion,tool:vendors[bound().vendor].name,version:bound().toolVersion,package:bound().package,adapter:bound().vendor,scope:state.scope||'all',outcome:state.outcome||'fail',simulation:true};state.busy=true;render();setTimeout(()=>{state.busy=false;const id='run-'+String(state.runs.length+1).padStart(3,'0');const r={...invocation,id,raw:`SIMULATED OUTPUT — not original supplier output\nTool: ${invocation.tool} ${invocation.version}\nPackage: ${invocation.package}\nRevision: ${invocation.revision}\nEnvironment: ${invocation.bindingVersion}\nScope: ${invocation.scope}\nResult: ${invocation.outcome}\n${({pass:'Selected example checks completed.',fail:'Illustrative diagnostic: controller timing requires review.',partial:'Illustrative external check did not finish.',error:'Illustrative license checkout failure; no checks ran.'})[invocation.outcome]}`};state.runs.unshift(r);state.recordId=id;render();notify('Example invocation recorded. No supplier process was called.')},1000)}
function handleAction(action){switch(action){case'theme':state.theme=state.theme==='dark'?'light':'dark';render();break;case'scan':notify('Example inventory refreshed. No machine scan was performed.');break;case'prepare':prepare();break;case'discard':state.pending=null;render();notify('Pending preview discarded.');break;case'confirm':{const p=state.pending;if(!p||p.revision!==state.revision||p.bindingVersion!==state.bindingVersion||state.busy){notify('Preview is stale. Prepare it again.');return}openDialog('Apply reviewed change?',`<p>CanControllerBaudRate: <strong>${p.before} → ${p.after} kbit/s</strong></p><p class="mono">Config/Can.arxml</p><div class="callout">An example snapshot is retained for one-step Undo. Existing validation evidence becomes stale.</div>`,'Apply change',()=>{if(state.busy||p!==state.pending||p.revision!==state.revision||p.bindingVersion!==state.bindingVersion){notify('Context changed; application rejected.');return}state.undo={value:state.value,bindingVersion:state.bindingVersion};state.value=p.after;state.revision++;state.history.unshift({kind:'apply',before:p.before,after:p.after,revision:state.revision});state.pending=null;render();notify('Example change applied. Old evidence remains bound to the previous revision.');});break}case'undo':if(state.undo&&!state.busy){const old=state.value;state.value=state.undo.value;state.undo=null;state.revision++;state.pending=null;state.history.unshift({kind:'undo',before:old,after:state.value,revision:state.revision});render();notify('Previous example value restored in a new revision. Validation was not run.')}break;case'run':execute();break;case'inspect':if(state.busy)return;state.busy=true;render();setTimeout(()=>{state.busy=false;state.structural={revision:state.revision};render();notify('Example inspection complete: one unresolved reference. No supplier checks ran.')},600);break;case'locateBaud':state.selectedObject='baud';state.query='';state.kind='all';navigate('objects');break;case'locateSwc':state.selectedObject='swc';state.query='';state.kind='all';navigate('objects');break;case'copyPath':copy(objectSeed.find(x=>x.id===state.selectedObject).path);break;case'exportEvidence':exportRecord();break;case'saveBinding':{if(state.busy)return;const project=$('#bindingProject').value.trim();const v=$('#bindingVendor').value;const version=$('#bindingToolVersion').value.trim();const error=$('#bindingError');if(!project||!version){error.hidden=false;error.textContent='Enter a project name and tool version. Missing packages may be saved but block execution.';(!project?$('#bindingProject'):$('#bindingToolVersion')).focus();return}const next={project,vendor:v,toolVersion:version,package:$('#bindingPackage').value.trim(),location:$('#bindingLocation').value.trim()};if(JSON.stringify(next)===JSON.stringify(bound())){notify('Binding unchanged.');return}state.binding=next;state.bindingVersion++;state.pending=null;state.undo=null;render();notify('Example binding saved. Previous evidence is stale; no installation or license was verified.');break}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.go){navigate(b.dataset.go,b.dataset.tab);return}if(b.dataset.vendor){state.vendor=b.dataset.vendor;render();document.querySelector(`[data-vendor="${state.vendor}"]`)?.focus({preventScroll:true});return}if(b.dataset.object){state.selectedObject=b.dataset.object;if(state.view!=='objects'){state.query='';state.kind='all';navigate('objects')}else{render();$('#screen h2')?.setAttribute('tabindex','-1');$('#screen h2')?.focus({preventScroll:true})}return}if(b.dataset.record){state.recordId=b.dataset.record;render();notify('Showing evidence '+state.recordId);return}if(b.dataset.tab){state.tab=b.dataset.tab;render();document.querySelector(`[data-tab="${state.tab}"]`)?.focus();return}if(b.dataset.contract){copy(JSON.stringify(requestFor(b.dataset.contract),null,2));return}if(b.dataset.action)handleAction(b.dataset.action)});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='mobileNav'){navigate(e.target.value);return}const mapping={catalogRegion:'catalogRegion',kind:'kind',contractType:'contractType',scope:'scope',outcome:'outcome'};if(mapping[id]){state[mapping[id]]=e.target.value;render();$('#'+id)?.focus()}});
document.addEventListener('input',e=>{const id=e.target.id;const map={catalogQuery:'catalogQuery',objectQuery:'query',contractQuery:'contractQuery'};if(map[id]){const pos=e.target.selectionStart;state[map[id]]=e.target.value;render();const input=$('#'+id);input.focus();input.setSelectionRange(pos,pos)}if(id==='baud'){state.draft=e.target.value;if(state.pending){state.pending=null;save();notify('Value changed. Prepare a fresh preview before applying.');render();$('#baud').focus()}}});
document.addEventListener('keydown',e=>{if(e.isComposing||e.repeat||$('#dialog').open)return;if(e.key==='Enter'&&e.target.id==='baud'){e.preventDefault();prepare()}if((e.ctrlKey||e.metaKey)&&e.key===','){e.preventDefault();navigate('settings')}if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.target.closest('input,select,textarea,[contenteditable]')){const q=$('#objectQuery')||$('#catalogQuery')||$('#contractQuery');if(q){e.preventDefault();q.focus()}}});
$('#dialogCancel').onclick=()=>$('#dialog').close();$('#dialogConfirm').onclick=()=>{const action=dialogAction;$('#dialog').close();action?.()};$('#dialog').addEventListener('close',()=>{dialogAction=null;if(dialogTrigger?.isConnected)dialogTrigger.focus();else {const heading=$('#screen h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})}});$('#theme').onclick=()=>handleAction('theme');render();
